const textBlock = (text: string, style = "normal") => ({
  _type: "block",
  _key: text.toLowerCase().replace(/[^a-z0-9]+/g, "-").slice(0, 60),
  style,
  markDefs: [],
  children: [{ _type: "span", _key: "span", text, marks: [] }],
});

const paragraph = (text: string) => textBlock(text);
const heading = (text: string) => textBlock(text, "h2");
const bullet = (text: string) => ({
  ...textBlock(text),
  listItem: "bullet" as const,
  level: 1,
});

